            ? type(IERC165).interfaceId
            : type(IERC165).interfaceId;
        if (selector % 3 == 0) {
            id = type(IAccessControl).interfaceId;
        }
        bool ok = c.supportsInterface(id);
        assertTrue(ok);
    }
}

