pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // IAccessControl interface id = XOR of its declared function selectors
        bytes4 hasRoleSel = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 getRoleAdminSel = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 grantRoleSel = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 revokeRoleSel = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 renounceRoleSel = bytes4(keccak256("renounceRole(bytes32,address)"));
        bytes4 accessControlId = hasRoleSel ^ getRoleAdminSel ^ grantRoleSel ^ revokeRoleSel ^ renounceRoleSel;
        // ERC165 id, computed from the signature (the interface's only function)
        bytes4 erc165Id = bytes4(keccak256("supportsInterface(bytes4)"));

        bool expected = (interfaceId == accessControlId) || (interfaceId == erc165Id);
        assertTrue(c.supportsInterface(interfaceId) == expected);
    }
}

