pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControlProbe {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

interface IERC165Probe {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 id) public {
        // Derive the AccessControl interface id on-chain from its five selectors.
        bytes4 acId =
            IAccessControlProbe.hasRole.selector ^
            IAccessControlProbe.getRoleAdmin.selector ^
            IAccessControlProbe.grantRole.selector ^
            IAccessControlProbe.revokeRole.selector ^
            IAccessControlProbe.renounceRole.selector;
        bytes4 erc165Id = IERC165Probe.supportsInterface.selector;

        bool ok = c.supportsInterface(id);

        // General rule: the timelock advertises exactly the ERC-165 introspection
        // interface AND the full AccessControl interface (id derived from its
        // selectors), and nothing else. The mutant drops the AccessControl
        // advertisement, so for id == acId it returns false.
        assertTrue(ok == (id == acId || id == erc165Id));
    }
}

