pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 id) public {
        // The contract must advertise support for both its ERC165 and AccessControl
        // interfaces, and for any other fuzzed id it must answer exactly whether
        // that id is one of those two interface ids (no other id is supported).
        bool erc165 = c.supportsInterface(type(IERC165).interfaceId);
        bool accessControl = c.supportsInterface(type(IAccessControl).interfaceId);
        bool reflected = c.supportsInterface(id);
        assertTrue(
            erc165 && accessControl
                && reflected == (id == type(IERC165).interfaceId || id == type(IAccessControl).interfaceId)
        );
    }
}
interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
}

