    bytes4 constant ERC165_ID = bytes4(keccak256("supportsInterface(bytes4)"));
    bytes4 constant ACCESSCONTROL_ID =
        bytes4(keccak256("hasRole(bytes32,address)")) ^
        bytes4(keccak256("getRoleAdmin(bytes32)")) ^
        bytes4(keccak256("grantRole(bytes32,address)")) ^
        bytes4(keccak256("revokeRole(bytes32,address)")) ^
        bytes4(keccak256("renounceRole(bytes32,address)"));

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 interfaceId) public {
        bool expected = (interfaceId == ERC165_ID) || (interfaceId == ACCESSCONTROL_ID);
        bool ok;
        try c.supportsInterface(interfaceId) returns (bool supported) {
            ok = supported;
        } catch {
            ok = false;
        }
        assertTrue(ok == expected, "supportsInterface must honor ERC165/AccessControl ids");
    }
}

